create table if not exists public.global_ui_labels (key text primary key, eng text not null check (btrim(eng) <> ''), bng text not null check (btrim(bng) <> ''), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create or replace function public.set_global_ui_labels_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
drop trigger if exists trg_global_ui_labels_updated_at on public.global_ui_labels;
create trigger trg_global_ui_labels_updated_at before update on public.global_ui_labels for each row execute function public.set_global_ui_labels_updated_at();
insert into public.global_ui_labels(key,eng,bng) values ('menu','Menu','উঠান'),('login','Login','বাড়ি'),('back','Back','পেছনে'),('search','Search','খোঁজ'),('home','Home','গ্রাম'),('close','Close','বন্ধ'),('profile','Profile','পরিচয়'),('information','Information','গ্রামের কথা'),('posts','Posts','খবর'),('post','Post','খবর'),('albums','Albums','ছবির খাতা'),('album','Album','ছবির খাতা'),('gallery','Gallery','ছবির ঘর'),('notice','Notice','জানানো কথা'),('events','Events','আয়োজন'),('members','Members','মানুষজন'),('contact','Contact','যোগাযোগ'),('settings','Settings','গোছগাছ'),('notifications','Notifications','বার্তা'),('messages','Messages','চিঠি'),('comments','Comments','মতামত'),('photos','Photos','ছবি'),('videos','Videos','ভিডিও'),('documents','Documents','কাগজপত্র'),('help','Help','সহায়তা'),('about','About','পরিচয়'),('language','Language','ভাষা'),('bengali','Bengali','বাংলা'),('english','English','ইংরেজি'),('day','Day','দিন'),('night','Night','রাত'),('logout','Logout','বেরোনো'),('save','Save','রাখা'),('edit','Edit','বদল'),('delete','Delete','মোছা'),('add','Add','যোগ'),('remove','Remove','বাদ'),('share','Share','ভাগ'),('download','Download','নামানো'),('upload','Upload','তোলা'),('refresh','Refresh','নতুন'),('loading','Loading','আসছে'),('dashboard','Dashboard','কাজের ঘর'),('admin','Admin','দায়িত্ব'),('user','User','মানুষ') on conflict (key) do nothing;
alter table public.global_ui_labels enable row level security;
drop policy if exists global_ui_labels_public_read on public.global_ui_labels;
create policy global_ui_labels_public_read on public.global_ui_labels for select to anon, authenticated using (true);
drop policy if exists global_ui_labels_admin_write on public.global_ui_labels;
create policy global_ui_labels_admin_write on public.global_ui_labels for all to authenticated using (private.has_permission('settings_manage')) with check (private.has_permission('settings_manage'));